#Requires -Version 5.1
# feat-asignaciones-estado-snapshot.ps1
#
# IMPLEMENTACION:
#
# 1. MIGRACION SQL (supabase/migrations/043_asignaciones_estado_snapshot.sql)
#    Nuevas columnas en asignaciones:
#      - estado_obra_snapshot_id     UUID -> estados_obra
#      - estado_obra_snapshot_nombre TEXT (inmutable)
#      - estado_obra_snapshot_color  TEXT (inmutable)
#      - snapshot_estimado           BOOLEAN (true = reconstruido, no tiempo real)
#
#    Trigger BEFORE INSERT: trg_asignaciones_snapshot_estado
#      Lee el estado actual de obras.estado_obra_id en el momento del INSERT
#      Lo guarda en las 3 columnas snapshot, snapshot_estimado = false
#      Funciona para TODOS los INSERT: planificador, obra-detail, cualquier cliente
#
#    Backfill asignaciones existentes:
#      1) Busca en audit_log el ultimo UPDATE de estado ANTERIOR a created_at
#      2) Si no hay registro -> usa estado actual de la obra
#      3) snapshot_estimado = true en todos los casos de backfill
#
# 2. obra-detail.tsx (MODIFICADO)
#    - Query incluye campos snapshot
#    - Pestaña Recursos: una fila por asignacion individual (no agrupado)
#    - Nueva columna "Estado al asignar" con badge coloreado
#    - Si snapshot_estimado = true: indicador "~" con tooltip
#    - Orden: recurso ASC, fecha_inicio ASC
#
# 3. planificacion/page.tsx (MODIFICADO)
#    Solo comentarios — el trigger hace todo el trabajo en BD
#    No es necesario pasar datos adicionales desde el cliente
#
# EJECUCION OBLIGATORIA EN SUPABASE SQL EDITOR:
#   Copiar y ejecutar el contenido de supabase/migrations/043_asignaciones_estado_snapshot.sql
#   (el script de PowerShell escribe el archivo pero no ejecuta SQL)

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: snapshot estado obra en asignaciones" -ForegroundColor Cyan

Write-Host "  -> supabase\migrations\043_asignaciones_estado_snapshot.sql" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "supabase\migrations\043_asignaciones_estado_snapshot.sql")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "supabase\migrations\043_asignaciones_estado_snapshot.sql"), $bytes)
Write-Host "  OK: 4 KB" -ForegroundColor Green

Write-Host "  -> src\app\obras\[id]\obra-detail.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\obras\[id]\obra-detail.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\obras\[id]\obra-detail.tsx"), $bytes)
Write-Host "  OK: 48 KB" -ForegroundColor Green

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 74 KB" -ForegroundColor Green

$detail = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\obras\[id]\obra-detail.tsx"), [System.Text.Encoding]::UTF8)
$sql    = [System.IO.File]::ReadAllText((Join-Path $RepoPath "supabase\migrations\043_asignaciones_estado_snapshot.sql"), [System.Text.Encoding]::UTF8)
if ($detail.Contains("estado_obra_snapshot_nombre")) { Write-Host "  OK: columna snapshot en obra-detail" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($detail.Contains("Estado al asignar"))           { Write-Host "  OK: cabecera tabla" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($detail.Contains("snapshot_estimado"))           { Write-Host "  OK: indicador estimado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($sql.Contains("trg_asignaciones_snapshot_estado")) { Write-Host "  OK: trigger en migracion" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($sql.Contains("snapshot_estimado"))              { Write-Host "  OK: backfill con flag estimado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  PASO CRITICO: Ejecutar en Supabase SQL Editor:" -ForegroundColor Yellow
Write-Host "  supabase\migrations\043_asignaciones_estado_snapshot.sql" -ForegroundColor Yellow
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "feat: snapshot estado obra al crear asignacion"'
Write-Host "  git push"
